#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x, y, z;
    cin >> x >> y >> z;

    long long weeks = min({x / 3, y / 2, z / 2});
    x -= weeks * 3;
    y -= weeks * 2;
    z -= weeks * 2;

    const int schedule[7] = {0, 1, 2, 0, 2, 1, 0};
    long long best = 0;

    for (int start = 0; start < 7; ++start) {
        long long food[3] = {x, y, z};
        long long days = 0;

        while (food[schedule[(start + days) % 7]] > 0) {
            --food[schedule[(start + days) % 7]];
            ++days;
        }

        best = max(best, days);
    }

    cout << weeks * 7 + best;
    return 0;
}

